import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import styled from "styled-components";
import PageWrapper from "../components/PageWrapper";

// --- Styled Components ---
const HomeWrapper = styled.div`
  padding: 60px 40px;
  font-family: "Roboto", sans-serif;
  display: flex;
  flex-direction: column;
  gap: 50px;
`;

const Section = styled.div`
  display: flex;
  justify-content: center;
  align-items: center;
  flex-direction: column;
  padding: 60px 30px;
  border-radius: 12px;
  position: relative;
  overflow: hidden;
  width: 100%;
  max-width: 900px;
  margin: 0 auto;
  cursor: pointer;

  background: ${({ darkMode }) =>
    darkMode
      ? "linear-gradient(135deg, #2c2c2c, #1e1e1e)"
      : "linear-gradient(135deg, #f0f0f0, #ffffff)"};

  box-shadow: ${({ darkMode }) =>
    darkMode
      ? "0 10px 25px rgba(0,0,0,0.7)"
      : "0 10px 25px rgba(0,0,0,0.15)"};

  transition: all 0.4s ease;

  &:hover {
    transform: scale(1.02);
  }
`;

const SectionTitle = styled.h2`
  font-size: 32px;
  color: ${({ darkMode }) => (darkMode ? "#e50914" : "#e74c3c")};
  margin-bottom: 16px;
  text-align: center;
`;

const SectionDescription = styled.p`
  font-size: 18px;
  color: ${({ darkMode }) => (darkMode ? "#ccc" : "#555")};
  text-align: center;
  margin-bottom: 24px;
  max-width: 600px;
`;

const StyledButton = styled(Link)`
  background-color: #e50914;
  color: #fff;
  padding: 16px 36px;
  border-radius: 8px;
  text-decoration: none;
  font-size: 18px;
  font-weight: 500;
  transition: all 0.3s ease;

  &:hover {
    background-color: #ff1a2d;
    transform: translateY(-2px);
  }
`;

const Mosaic = styled.div`
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: ${({ color1, color2 }) =>
    `linear-gradient(135deg, ${color1}, ${color2})`};
  opacity: 0.25;
  z-index: 0;
`;

const ContentWrapper = styled.div`
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
`;

const Home = () => {
  const [darkMode, setDarkMode] = useState(
    window.matchMedia &&
    window.matchMedia("(prefers-color-scheme: dark)").matches
  );

  useEffect(() => {
    document.body.style.background = darkMode ? "#1e1e1e" : "#f5f5f5";
    document.body.style.color = darkMode ? "#e0e0e0" : "#121212";
  }, [darkMode]);

  return (
    <PageWrapper>
      <HomeWrapper>
        <Section darkMode={darkMode}>
          <Mosaic color1="#C0FDFB" color2="#FEE9E1" />
          <ContentWrapper>
            <SectionTitle darkMode={darkMode}>
              Welcome to My Book Library 📚
            </SectionTitle>
            <SectionDescription darkMode={darkMode}>
              Manage your book collection, discover new books, and keep your
              library up-to-date.
            </SectionDescription>
            <StyledButton to="/books">Explore All Books</StyledButton>
          </ContentWrapper>
        </Section>

        <Section darkMode={darkMode}>
          <Mosaic color1="#FEE9E1" color2="#90E0EF" />
          <ContentWrapper>
            <SectionTitle darkMode={darkMode}>Add a New Book</SectionTitle>
            <SectionDescription darkMode={darkMode}>
              Want to add a new book to your library? Use this section to add
              your personal collection.
            </SectionDescription>
            <StyledButton to="/add">Add Book</StyledButton>
          </ContentWrapper>
        </Section>

        <Section darkMode={darkMode}>
          <Mosaic color1="#90E0EF" color2="#F8F7FF" />
          <ContentWrapper>
            <SectionTitle darkMode={darkMode}>My Book Collection</SectionTitle>
            <SectionDescription darkMode={darkMode}>
              View and manage all the books you have added to your personal
              library.
            </SectionDescription>
            <StyledButton to="/mybooks">View My Books</StyledButton>
          </ContentWrapper>
        </Section>

        <Section darkMode={darkMode}>
          <Mosaic color1="#F8F7FF" color2="#C0FDFB" />
          <ContentWrapper>
            <SectionTitle darkMode={darkMode}>About This App</SectionTitle>
            <SectionDescription darkMode={darkMode}>
              Learn more about how this app works and how you can manage your
              book collection effortlessly.
            </SectionDescription>
            <StyledButton to="/about">Learn More</StyledButton>
          </ContentWrapper>
        </Section>
      </HomeWrapper>
    </PageWrapper>
  );
};

export default Home;
